import { describe, expect, it } from '@jest/globals';
import type { PaginatedResponse } from '@/interfaces/IPaginatedResponse';
import { fireEvent, render, screen } from '@testing-library/react';
import type { HTMLAttributes } from 'react';
import {
    countPendenciasAbertas,
    patchPendenciaEmAnaliseInPage,
} from '../ViewModels/PendenciasScreen/useViewModelPendenciasScreen';
import {
    countOpenPendencias,
    getPendenciasData,
    hasOpenImpeditivaPendencia,
} from '../utils/getPendenciasData';
import { RightPanel } from '../Views/PendenciasScreen/RightPanel';
import { CenterPanel } from '../Views/PendenciasScreen/CenterPanel';
import { LeftPanel } from '../Views/PendenciasScreen/LeftPanel';
import type {
    TPendencia,
    TPendenciaListagem,
    TPendenciasAtivo,
} from '../types/pendencia';
import {
    isPendenciaAberta,
    isPendenciaEmAnalise,
    isPendenciaNaoResolvida,
    isPendenciaResolvida,
    normalizePendenciaStatus,
    PENDENCIA_STATUS,
} from '../utils/pendenciaStatus';

jest.mock('nuqs', () => ({
    parseAsInteger: { withDefault: jest.fn(() => ({})) },
    parseAsString: { withDefault: jest.fn(() => ({})) },
    useQueryState: jest.fn(() => [null, jest.fn()]),
}));

jest.mock('framer-motion', () => ({
    motion: {
        div: ({ children, ...props }: HTMLAttributes<HTMLDivElement>) => (
            <div {...props}>{children}</div>
        ),
    },
    useReducedMotion: () => true,
}));

function buildPendencia(overrides: Partial<TPendencia> = {}): TPendencia {
    return {
        id: 1,
        titulo: 'Pendência teste',
        categoria: 'Documentação',
        descricao: 'Descrição',
        especie: 'ativo',
        natureza: 'operacional',
        vinculo: null,
        severidade: 'media',
        impedimento: false,
        status: PENDENCIA_STATUS.NAO_RESOLVIDA,
        registrado_por: 'Analista',
        data_registro: '2026-06-01',
        visivel_broker: false,
        documentos: [],
        esclarecimento: null,
        tentativas_anteriores: [],
        ...overrides,
    };
}

function buildListagem(pendencias: TPendencia[]): TPendenciaListagem {
    return {
        ativo: pendencias,
        certidoes: [],
        processos: [],
    };
}

describe('pendenciaStatus utils', () => {
    it('normalizes unsupported, null and undefined values to the initial status', () => {
        expect(normalizePendenciaStatus('desconhecido')).toBe(PENDENCIA_STATUS.NAO_RESOLVIDA);
        expect(normalizePendenciaStatus(null)).toBe(PENDENCIA_STATUS.NAO_RESOLVIDA);
        expect(normalizePendenciaStatus(undefined)).toBe(PENDENCIA_STATUS.NAO_RESOLVIDA);
    });

    it('identifies each supported status', () => {
        expect(isPendenciaNaoResolvida({ status: PENDENCIA_STATUS.NAO_RESOLVIDA })).toBe(true);
        expect(isPendenciaEmAnalise({ status: PENDENCIA_STATUS.EM_ANALISE })).toBe(true);
        expect(isPendenciaResolvida({ status: PENDENCIA_STATUS.RESOLVIDA })).toBe(true);
        expect(isPendenciaResolvida(undefined)).toBe(false);
    });

    it('maps API status aliases (aberta, em_resolucao)', () => {
        expect(normalizePendenciaStatus('aberta')).toBe(PENDENCIA_STATUS.NAO_RESOLVIDA);
        expect(normalizePendenciaStatus('em_resolucao')).toBe(PENDENCIA_STATUS.RESOLVIDA);
        expect(normalizePendenciaStatus('em_analise')).toBe(PENDENCIA_STATUS.EM_ANALISE);
    });
});

describe('getPendenciasData card helpers', () => {
    function buildCardItem(
        pendencias: TPendenciaListagem | null | undefined,
    ): { pendencias?: TPendenciaListagem | null } {
        return { pendencias };
    }

    it('getPendenciasData returns empty array when pendencias is missing or empty', () => {
        expect(getPendenciasData(buildCardItem(null))).toEqual([]);
        expect(getPendenciasData(buildCardItem(undefined))).toEqual([]);
        expect(getPendenciasData(buildCardItem(buildListagem([])))).toEqual([]);
    });

    it('countOpenPendencias counts every non-resolved pendencia, including em_analise', () => {
        const item = buildCardItem(
            buildListagem([
                buildPendencia({ id: 1, status: PENDENCIA_STATUS.NAO_RESOLVIDA }),
                buildPendencia({ id: 2, status: PENDENCIA_STATUS.EM_ANALISE }),
                buildPendencia({ id: 3, status: PENDENCIA_STATUS.RESOLVIDA }),
                buildPendencia({ id: 4, status: PENDENCIA_STATUS.NAO_RESOLVIDA }),
            ]),
        );

        expect(countOpenPendencias(item)).toBe(3);
    });

    it('countOpenPendencias returns 0 for empty or invalid pendencias', () => {
        expect(countOpenPendencias({})).toBe(0);
        expect(countOpenPendencias({ pendencias: null })).toBe(0);
        expect(countOpenPendencias({ pendencias: undefined })).toBe(0);
    });

    it('countOpenPendencias excludes em_resolucao alias (resolved)', () => {
        const item = buildCardItem(
            buildListagem([buildPendencia({ id: 1, status: PENDENCIA_STATUS.RESOLVIDA })]),
        );
        expect(countOpenPendencias(item)).toBe(0);
    });

    it('hasOpenImpeditivaPendencia detects open impeditiva only', () => {
        const openImpeditiva = buildCardItem(
            buildListagem([
                buildPendencia({ id: 1, status: PENDENCIA_STATUS.NAO_RESOLVIDA, impedimento: true }),
            ]),
        );
        const emAnaliseImpeditiva = buildCardItem(
            buildListagem([
                buildPendencia({ id: 2, status: PENDENCIA_STATUS.EM_ANALISE, impedimento: true }),
            ]),
        );
        const resolvedImpeditiva = buildCardItem(
            buildListagem([
                buildPendencia({ id: 3, status: PENDENCIA_STATUS.RESOLVIDA, impedimento: true }),
            ]),
        );
        const openNonImpeditiva = buildCardItem(
            buildListagem([
                buildPendencia({
                    id: 4,
                    status: PENDENCIA_STATUS.NAO_RESOLVIDA,
                    impedimento: false,
                }),
            ]),
        );

        expect(hasOpenImpeditivaPendencia(openImpeditiva)).toBe(true);
        expect(hasOpenImpeditivaPendencia(emAnaliseImpeditiva)).toBe(true);
        expect(hasOpenImpeditivaPendencia(resolvedImpeditiva)).toBe(false);
        expect(hasOpenImpeditivaPendencia(openNonImpeditiva)).toBe(false);
    });

    it('matches useViewModelDueCard openPends and hasImpeditiva rules', () => {
        const item = buildCardItem(
            buildListagem([
                buildPendencia({ id: 1, status: PENDENCIA_STATUS.NAO_RESOLVIDA, impedimento: true }),
                buildPendencia({ id: 2, status: PENDENCIA_STATUS.EM_ANALISE, impedimento: true }),
                buildPendencia({ id: 3, status: PENDENCIA_STATUS.RESOLVIDA, impedimento: false }),
            ]),
        );
        const pendenciasData = getPendenciasData(item);
        const openPends = pendenciasData.filter((p) => isPendenciaAberta(p));

        expect(countOpenPendencias(item)).toBe(openPends.length);
        expect(hasOpenImpeditivaPendencia(item)).toBe(openPends.some((p) => p.impedimento));
    });
});

